INSERT INTO notice (title,content,type,publisher_id,publisher_name,status,create_time) VALUES
('关于开展 2026 年秋季实验室安全培训的通知','为落实实验室安全管理制度，所有进入化学、生物类实验室的同学须先完成线上安全培训与考核。请于本月 30 日前登录系统完成学习，考核合格后方可预约相关实验室。','NOTICE',1,'系统管理员',1,DATE_ADD(DATE_ADD(CURDATE(), INTERVAL -3 DAY), INTERVAL 10 HOUR)),
('实验楼 B 区网络设备维护公告','实验楼 B 区将于本周六 08:00-12:00 进行核心交换机升级，期间网络工程实验室暂停开放，已提交的预约将由管理员统一调整，请留意站内通知。','MAINTENANCE',1,'系统管理员',1,DATE_ADD(DATE_ADD(CURDATE(), INTERVAL -6 DAY), INTERVAL 10 HOUR)),
('大型仪器设备共享预约规则调整','自下月起，单价 10 万元以上设备单次预约时长上限调整为 4 小时，连续预约需间隔 1 小时，以便更多师生使用。','NOTICE',1,'系统管理员',1,DATE_ADD(DATE_ADD(CURDATE(), INTERVAL -9 DAY), INTERVAL 10 HOUR)),
('实验室预约系统上线试运行说明','本系统已上线试运行，支持实验室查询、在线预约、审批流转、设备报修等功能。使用中如遇问题，请联系设备管理处（电话：8888）。','SYSTEM',1,'系统管理员',1,DATE_ADD(DATE_ADD(CURDATE(), INTERVAL -20 DAY), INTERVAL 10 HOUR)),
('虚拟仿真实训室开放免审批预约','为提升使用效率，虚拟仿真实训室（LAB-D105）与创新创业工作室（LAB-D201）调整为免审批模式，提交预约后即时生效，请按预约时段刷卡入场。','NOTICE',1,'系统管理员',1,DATE_ADD(DATE_ADD(CURDATE(), INTERVAL -12 DAY), INTERVAL 10 HOUR)),
('关于加强实验设备日常巡检的通知','各实验室负责人需每周对管辖设备进行一次巡检，发现异常及时在系统中提交报修工单，维修完成后由报修人验收确认。','NOTICE',1,'系统管理员',1,DATE_ADD(DATE_ADD(CURDATE(), INTERVAL -1 DAY), INTERVAL 10 HOUR));
